def qft_6() -> QuantumCircuit:
    def qft(circuit, n):
        for i in range(n):
            circuit.h(i)
            for j in range(i + 1, n):
                circuit.cp(pi / (2 ** (j - i)), j, i)
        for i in range(n // 2):
            circuit.swap(i, n - i - 1)

    qr = QuantumRegister(6)
    cr = ClassicalRegister(6)
    qc = QuantumCircuit(qr, cr)
    qft(qc, 6)
    qc.measure(qr, cr)
    return qc

