def shor_7mod15() -> QuantumCircuit:
    n_count = 8
    qc = QuantumCircuit(n_count + 4, n_count)

    for q in range(n_count):
        qc.h(q)

    def controlled_multiply(qc, control_qubit, multiply_by):
        for i in range(4):
            qc.cx(control_qubit, n_count + i)
        for i in range(multiply_by - 1):
            for j in range(4):
                qc.cx(n_count + j, n_count + (j + 1) % 4)

    for i in range(n_count):
        controlled_multiply(qc, i, 7)

    qc.append(QFT(n_count, do_swaps=False).inverse(), range(n_count))

    qc.measure(range(n_count), range(n_count))
    return qc

