def Qadd_extend_4bit(a: str, b: str, c0: str) -> QuantumCircuit:
    n = 4
    qr = QuantumRegister(2*n + 1, 'q')
    cr = ClassicalRegister(n + 1, 'c')
    qc = QuantumCircuit(qr, cr)

    for i in range(n):
        if a[n - 1 - i] == '1':
            qc.x(qr[i])
        if b[n - 1 - i] == '1':
            qc.x(qr[n + i])

    if c0 == '1':
        qc.x(qr[2*n])

    def majority(qc, a, b, c):
        qc.cx(c, b)
        qc.cx(c, a)
        qc.ccx(a, b, c)

    def unmaj(qc, a, b, c):
        qc.ccx(a, b, c)
        qc.cx(c, a)
        qc.cx(a, b)

    for i in range(n):
        majority(qc, qr[i], qr[n + i], qr[n + i + 1])

    qc.cx(qr[2*n], qr[2*n - 1])

    for i in range(n - 1, -1, -1):
        unmaj(qc, qr[i], qr[n + i], qr[n + i + 1])

    for i in range(n):
        qc.measure(qr[n + i], cr[i])

    qc.measure(qr[2*n], cr[n])

    return qc

