from qiskit.algorithms import AmplificationProblem, Grover

def grover_knapsack_multiple_targets(weights, W, iterations=2, shots=1024) -> QuantumCircuit:
    num_qubits = len(weights)
    oracle = QuantumCircuit(num_qubits)
    for i in range(2 ** num_qubits):
        binary = format(i, f'0{num_qubits}b')
        total_weight = sum(int(binary[j]) * weights[j] for j in range(num_qubits))
        if total_weight == W:
            for qubit in range(num_qubits):
                if binary[qubit] == '0':
                    oracle.x(qubit)
            oracle.mcx(list(range(num_qubits)), num_qubits - 1)
            for qubit in range(num_qubits):
                if binary[qubit] == '0':
                    oracle.x(qubit)

    grover_op = GroverOperator(oracle)
    problem = AmplificationProblem(grover_op)
    grover = Grover(iterations=iterations)
    circuit = grover.construct_circuit(problem)
    circuit.measure_all()

    return circuit

