def qaoa_tsp() -> QuantumCircuit:
    n = 3
    dist = np.array([[0, 10, 15], [10, 0, 20], [15, 20, 0]])
    num_qubits = n * n

    def tsp_cost_function(x):
        x = x.reshape((n, n))
        cost = 0
        for i in range(n):
            for j in range(n):
                if x[i][j] == 1:
                    cost += dist[i][j]
        return cost

    def tsp_constraint(x):
        x = x.reshape((n, n))
        for i in range(n):
            if sum(x[i]) != 1:
                return False
        for j in range(n):
            if sum(x[:, j]) != 1:
                return False
        return True

    def create_hamiltonian():
        pauli_list = []
        for i in range(n):
            for j in range(n):
                w_ij = dist[i][j]
                for k in range(num_qubits):
                    if i != j:
                        z = ['I'] * num_qubits
                        z[k] = 'Z'
                        pauli_list.append((w_ij, ''.join(z)))
        return PauliSumOp.from_list(pauli_list)

    hamiltonian = create_hamiltonian()
    optimizer = COBYLA(maxiter=500)
    initial_point = np.random.rand(2)

    qaoa = QAOA(optimizer=optimizer, reps=1, initial_point=initial_point)
    sampler = Sampler()
    result = qaoa.compute_minimum_eigenvalue(hamiltonian, sampler=sampler)

    theta = Parameter('θ')
    qc = QuantumCircuit(num_qubits)
    for i in range(num_qubits):
        qc.h(i)
    for i, coeff in enumerate(result.eigenstate):
        for j in range(num_qubits):
            qc.rz(theta * coeff, j)
    return qc

