import numpy as np

def qaoa_tsp() -> QuantumCircuit:
    n_cities = 3
    adjacency_matrix = np.array([[0, 10, 15], [10, 0, 20], [15, 20, 0]])

    def create_tsp_hamiltonian(adj_matrix):
        n = len(adj_matrix)
        terms = []
        for i in range(n):
            for j in range(i+1, n):
                if adj_matrix[i, j] != 0:
                    terms.append((adj_matrix[i, j], i, j))
        hamiltonian_matrix = np.zeros((2**n, 2**n))
        for weight, i, j in terms:
            zz_term = np.identity(2**n)
            for k in range(n):
                if k == i or k == j:
                    zz_term = np.kron(zz_term, np.array([[1, 0], [0, -1]]))
                else:
                    zz_term = np.kron(zz_term, np.identity(2))
            hamiltonian_matrix += weight * zz_term
        return Operator(hamiltonian_matrix)

    def qaoa_ansatz(p):
        qr = QuantumRegister(n_cities, 'q')
        cr = ClassicalRegister(n_cities, 'c')
        qc = QuantumCircuit(qr, cr)
        beta = [Parameter(f'beta_{i}') for i in range(p)]
        gamma = [Parameter(f'gamma_{i}') for i in range(p)]

        for i in range(n_cities):
            qc.h(qr[i])

        for irep in range(p):
            for i in range(n_cities):
                for j in range(i+1, n_cities):
                    if adjacency_matrix[i, j] != 0:
                        qc.cx(qr[i], qr[j])
                        qc.rz(-2 * gamma[irep], qr[j])
                        qc.cx(qr[i], qr[j])

            for i in range(n_cities):
                qc.rx(2 * beta[irep], qr[i])

        qc.measure(qr, cr)
        return qc

    p = 1
    qaoa_circuit = qaoa_ansatz(p)
    sampler = Sampler()
    optimizer = COBYLA(maxiter=200)
    hamiltonian = create_tsp_hamiltonian(adjacency_matrix)
    qaoa_instance = QAOA(sampler=sampler, optimizer=optimizer, reps=p)
    qaoa_instance.compute_minimum_eigenvalue(hamiltonian, circuit=qaoa_circuit)
    return qaoa_circuit

